// What the pane says about a room, the same on every surface: the head's status line, the gate's word and why,
// its four conditions, how long ago GitHub was asked, and the one notice a room shows when something is wrong.
// Built from the model only: nothing is said that the sync state or the gate did not see.
import { pick } from './kit/lang'
import type { GateBadge, RoomView } from './state-types'
import { agoText } from './when'

const EN = {
  waitingPeer: 'Project room · waiting for a teammate',
  withPeer: (peer: string) => `Project room · you and ${peer}`,
  dmWaiting: 'Starts when your friend accepts',
  here: 'here',
  read: (ago: string) => `read ${ago}`,
  gate: { open: 'Gate open', closed: 'Gate closed', unknown: 'Gate pending' } as Record<GateBadge, string>,
  noMatch: 'No GitHub match',
  notPair: 'agents talk only in a two-person room',
  notCollab: (login: string) => `@${login} is not a collaborator`,
  otherRepo: 'this session is in another repo',
  askFirst: (login: string) => `@${login} · GitHub is asked on the first question`,
  readingRepo: (login: string) => `@${login} · reading the session's repo`,
  collab: (login: string) => `@${login} is a collaborator`,
  otherSide: 'The other side',
  confirmed: (who: string) => `${who} confirmed`,
  unconfirmed: (who: string) => `${who} not confirmed on GitHub`,
  collabRow: (login?: string) => (login === undefined ? 'Collaborator' : `@${login} · collaborator`),
  sessionRepo: 'This session\'s repo',
  notPairRow: 'Not a two-person room',
  pairRow: 'Two-person project room',
  notChecked: 'GitHub not asked yet; asked on the first question',
  checked: (ago: string) => `GitHub checked ${ago}`,
  troubled: 'Connection problem. The room will be read again shortly.',
  blocked: (who: string) => `${who} hasn't shared their mailbox with you yet. Ask them to share it on claude.ai.`,
  closed: (why: string) => `Agents are off: ${why}.`,
  spent: (limit: number) => `Your agent used today's ${limit} answers. New questions wait for your approval.`,
}

const TR: typeof EN = {
  waitingPeer: 'davet bekleniyor',
  withPeer: peer => `sen ve ${peer}`,
  dmWaiting: 'Arkadaşın daveti kabul edince başlar',
  here: 'burada',
  read: ago => `${ago} okudu`,
  gate: { open: 'Kapı açık', closed: 'Kapı kapalı', unknown: 'Kapı bekliyor' },
  noMatch: 'GitHub eşleşmesi yok',
  notPair: 'agent trafiği yalnızca iki kişilik odada',
  notCollab: login => `@${login} collaborator değil`,
  otherRepo: 'bu oturum başka bir repoda',
  askFirst: login => `@${login} · GitHub ilk soruda sorulur`,
  readingRepo: login => `@${login} · oturumun reposu okunuyor`,
  collab: login => `@${login} collaborator`,
  otherSide: 'Karşı taraf',
  confirmed: who => `${who} onaylı`,
  unconfirmed: who => `${who} GitHub'da onaylanmadı`,
  collabRow: login => (login === undefined ? 'collaborator' : `@${login} collaborator`),
  sessionRepo: 'Bu oturumun reposu',
  notPairRow: 'İki kişilik oda değil',
  pairRow: 'İki kişilik proje odası',
  notChecked: 'GitHub henüz sorulmadı; ilk soruda sorulur',
  checked: ago => `GitHub ${ago} kontrol edildi`,
  troubled: 'Bağlantı sorunu; oda birazdan yeniden okunacak.',
  blocked: who => `${who} kutusunu henüz seninle paylaşmadı; claude.ai'de paylaşmasını iste.`,
  closed: why => `Agent'lar kapalı: ${why}.`,
  spent: limit => `Agent'ının bugünkü ${limit} cevap hakkı doldu; yeni sorular onayını bekler.`,
}

const words = () => pick({ en: EN, tr: TR })

export type Status = { text: string; isHere: boolean }

// "here · read 1m ago" for a DM (each part only when known), "Project room · you and Leo" for a project. A
// mailbox that cannot be read is the notice line's to say, not the head's.
export function statusOf(room: RoomView, o: { now: number; isHere: boolean }): Status | null {
  const w = words()
  if (room.kind === 'project') return { text: room.peerName === undefined ? w.waitingPeer : w.withPeer(room.peerName), isHere: false }
  if (room.isWaiting) return { text: w.dmWaiting, isHere: false }
  const parts = [o.isHere ? w.here : '', room.peerReadTs > 0 ? w.read(agoText(room.peerReadTs, o.now)) : ''].filter(Boolean)
  return parts.length === 0 ? null : { text: parts.join(' · '), isHere: o.isHere }
}

export type GateWord = { paint: string; label: string; glyph: string }

const GATE_LOOK: Record<GateBadge, Omit<GateWord, 'label'>> = {
  open: { paint: 'ok', glyph: '⛨' },
  closed: { paint: 'danger', glyph: '⛨' },
  unknown: { paint: 'warn', glyph: '◷' },
}

export const gateWord = (badge: GateBadge): GateWord => ({ ...GATE_LOOK[badge], label: words().gate[badge] })

// Why the gate is what it is, in a few words: the first condition that fails, or the one still unknown.
export function gateDetail(room: RoomView): string {
  const c = room.project?.checks
  const w = words()
  if (c === undefined || !c.isConfirmed || c.login === undefined) return w.noMatch
  if (c.isPair === false) return w.notPair
  if (c.isCollaborator === false) return w.notCollab(c.login)
  if (c.isSessionRepo === false) return w.otherRepo
  if (c.isCollaborator === null) return w.askFirst(c.login)
  return c.isSessionRepo === null ? w.readingRepo(c.login) : w.collab(c.login)
}

export type CheckRow = { text: string; state: boolean | null; isMono?: boolean }

export function checkRows(room: RoomView): CheckRow[] {
  const c = room.project?.checks
  const w = words()
  const who = room.peerName ?? w.otherSide
  return [
    { text: c?.isConfirmed === true ? w.confirmed(who) : w.unconfirmed(who), state: c?.isConfirmed === true },
    { text: w.collabRow(c?.login), state: c?.isConfirmed === true ? c.isCollaborator : false },
    { text: w.sessionRepo, state: c?.isSessionRepo ?? null },
    { text: c?.isPair === false ? w.notPairRow : w.pairRow, state: c?.isPair !== false },
  ]
}

export const passedOf = (rows: readonly CheckRow[]): number => rows.filter(r => r.state === true).length

export function checkedText(room: RoomView, now: number): string {
  const at = room.project?.checks.checkedAt ?? null
  return at === null ? words().notChecked : words().checked(agoText(at, now))
}

// The one line a room shows under its head when something is wrong, most pressing first; null while all is well,
// so the gate and the budget stay out of sight. `hasWhy`: the line offers the room's details (the gate's checks).
export type Notice = { text: string; paint: 'warn' | 'danger'; hasWhy: boolean }

export function noticeOf(room: RoomView): Notice | null {
  const w = words()
  if (room.isTroubled) return { text: w.troubled, paint: 'warn', hasWhy: false }
  if (room.isBoxBlocked) return { text: w.blocked(room.peerName ?? w.otherSide), paint: 'warn', hasWhy: false }
  const p = room.project
  if (p === undefined) return null
  if (room.gate === 'closed') return { text: w.closed(gateDetail(room)), paint: 'danger', hasWhy: true }
  if (p.askUsed >= p.askLimit) return { text: w.spent(p.askLimit), paint: 'warn', hasWhy: false }
  return null
}

files.hooks/pane-agent.tsx:
// Agent traffic on the desktop. Each exchange is one line ("Leo's agent asked · diff · answered · 0 tokens")
// that opens on press: the question, who answered with what it cost, and a compact answer whose full text
// opens on a second press. A refusal stays a line in Flare, with nothing behind it. An agent's own note keeps its
// text, and an ask past the day's limit waits for the person as a compact draft. Words are native Text; only the
// lead glyph or face is Svg.
import type { RenderElement } from 'claude-code'

import { compactOf, FIRST_ROWS, type Compact } from './answers'
import { ANSWER_PREVIEW_LINES } from './limits'
import { GlyphPic, Pic, type Ctx } from './pane-kit'
import { tinyFace } from './sig-agent'
import { rowPart } from './sig-ui'
import type { Draft, Line } from './state-types'
import { avatarRole, initialsOf } from './theme'
import { firstName } from './tr'
import { askedArg, joined, messageOf, queryType, type Tx } from './traffic'
import { agentOf, answererOf, compactText, txSummary, viewLabel } from './tx-words'
import { clockText, secondsText } from './when'
import { chatWords } from './words-chat'
import { tokensText } from './words-count'
import { shownWire } from './words-wire'

const LEAD = 16
const FULL_SUFFIX = ':full'

// An opened answer's whole text is a second disclosure, kept under its own id.
export const fullIdOf = (txId: string): string => `${txId}${FULL_SUFFIX}`

function clipLines(text: string, isOpen: boolean): string {
  const lines = text.split('\n')
  if (isOpen || lines.length <= ANSWER_PREVIEW_LINES) return text
  return `${lines.slice(0, ANSWER_PREVIEW_LINES).join('\n')}\n${chatWords().moreLines(lines.length - ANSWER_PREVIEW_LINES)}`
}

// How many of a search's or a list's rows hide behind "Show all".
const hiddenOf = (c: Compact): number => (c.kind === 'hits' || c.kind === 'list' ? Math.max(0, c.count - FIRST_ROWS) : 0)

function Toggle(ctx: Ctx, o: { key: string; id: string; open: string; closed: string }): RenderElement {
  const { Button } = ctx.ui
  const isOpen = ctx.model.expanded.includes(o.id)
  return <Button key={o.key} label={isOpen ? o.open : o.closed} plain onPress={() => ctx.on.toggleExpanded(o.id)} />
}

// The compact answer (a stat, counts, the first hits), then "Show all" for the whole text.
function AnswerBody(ctx: Ctx, o: { tx: Tx; body: string }): RenderElement[] {
  const { Box, Text } = ctx.ui
  const fullId = fullIdOf(o.tx.id)
  const isFull = ctx.model.expanded.includes(fullId)
  const c = compactOf(queryType(o.tx), o.body)
  const full = <Text key="body" color={ctx.look.hi} wrap="wrap">{clipLines(shownWire(c.kind === 'text' ? c.text : o.body), isFull)}</Text>
  if (c.kind === 'text') return [full]
  const w = chatWords()
  const hidden = hiddenOf(c)
  const more = hidden === 0 ? '' : w.moreHidden({ n: hidden, isHits: c.kind === 'hits' })
  const toggle = Toggle(ctx, { key: `more-${o.tx.id}`, id: fullId, open: w.hide, closed: w.showAll })
  const row = <Box key="more" flexDirection="row" gap={1} alignItems="center">{more === '' ? null : <Text color={ctx.look.lo}>{more}</Text>}{toggle}</Box>
  return [<Text key="compact" color={ctx.look.hi} wrap="wrap">{compactText(c)}</Text>, row, ...(isFull ? [full] : [])]
}

// "Answered on this machine · 0 tokens · 0.4s ··· 14:12"; a free answer's tokens in the signal colour.
function AnswerMeta(ctx: Ctx, o: { tx: Tx; a: NonNullable<ReturnType<typeof joined>> }): RenderElement {
  const { Box, Text } = ctx.ui
  const { a } = o
  const who = a.line.isMine ? chatWords().thisMachine : answererOf(a)
  const q = o.tx.query === undefined ? null : messageOf(o.tx.query)
  const took = q === null ? '' : ` · ${secondsText(a.ts - q.ts)}`
  return (
    <Box key="answer-meta" flexDirection="row" gap={1}>
      <Box flexGrow={1} flexShrink={1}>
        <Text color={ctx.look.mid} wrap="truncate-end">
          <Text bold>{who}</Text>
          <Text color={a.tokens === 0 ? ctx.look.signal.fg : ctx.look.lo}>{` · ${tokensText(a.tokens)}`}</Text>
          <Text color={ctx.look.lo}>{took}</Text>
        </Text>
      </Box>
      <Text color={ctx.look.lo}>{clockText(a.ts)}</Text>
    </Box>
  )
}

function Detail(ctx: Ctx, tx: Tx): RenderElement {
  const { Box, Text } = ctx.ui
  const a = joined(tx)
  const question = queryType(tx) === 'ask' ? askedArg(tx) : undefined
  const kids: RenderElement[] = question === undefined ? [] : [<Text key="question" color={ctx.look.hi} wrap="wrap">{question}</Text>]
  if (a === null) kids.push(<Text key="waiting" color={ctx.look.lo}>{chatWords().waitingAnswer}</Text>)
  else kids.push(AnswerMeta(ctx, { tx, a }), ...AnswerBody(ctx, { tx, body: a.body }))
  return <Box key="detail" flexDirection="column" gap={1} backgroundColor={ctx.look.inset} paddingX={1} paddingY={1}>{kids}</Box>
}

// The asker's face, the robot for this side's agent, a lock for a refusal; keyed by its exchange or note.
function Lead(ctx: Ctx, o: { line: Line | undefined; isDenied: boolean; id: string }): RenderElement {
  const key = `lead-${o.id}`
  if (o.isDenied) return GlyphPic(ctx, { glyph: 'lock', paint: 'danger', key })
  if (o.line === undefined || o.line.isMine) return GlyphPic(ctx, { glyph: 'robot', paint: 'run', key })
  const face = tinyFace({ initials: initialsOf(o.line.authorName), paint: avatarRole(o.line.seed), size: LEAD })
  return Pic(ctx, rowPart({ width: LEAD, height: LEAD, left: [face], alt: '' }), key)
}

export function TxLine(ctx: Ctx, tx: Tx): RenderElement {
  const { Box, Text } = ctx.ui
  const s = txSummary(tx)
  const isDenied = s.outcome === 'denied'
  const isOpen = !isDenied && ctx.model.expanded.includes(tx.id)
  return (
    <Box key={`tx-${tx.id}`} flexDirection="column" gap={1}>
      <Box flexDirection="row" alignItems="center" gap={1}>
        {Lead(ctx, { line: tx.query, isDenied, id: tx.id })}
        <Box flexGrow={1} flexShrink={1}><Text color={isDenied ? ctx.look.role.danger.fg : ctx.look.mid} wrap="truncate-end">{s.text}</Text></Box>
        {isDenied ? null : Toggle(ctx, { key: `open-tx-${tx.id}`, id: tx.id, open: chatWords().hide, closed: viewLabel(tx) })}
      </Box>
      {isOpen ? Detail(ctx, tx) : null}
    </Box>
  )
}

// A note an agent posted with the send tool: who wrote it, then its text on the inset.
export function AgentNote(ctx: Ctx, line: Line): RenderElement {
  const { Box, Text } = ctx.ui
  const m = messageOf(line)
  return (
    <Box key={`msg-${line.id}`} flexDirection="column" gap={1}>
      <Box flexDirection="row" alignItems="center" gap={1}>
        {Lead(ctx, { line, isDenied: false, id: line.id })}
        <Box flexGrow={1}><Text color={ctx.look.role.run.fg} bold>{chatWords().wrote(agentOf(line))}</Text></Box>
        <Text color={ctx.look.lo}>{m === null ? '' : clockText(m.ts)}</Text>
      </Box>
      <Box backgroundColor={ctx.look.inset} paddingX={1} paddingY={1}><Text color={ctx.look.hi} wrap="wrap">{m?.text ?? ''}</Text></Box>
    </Box>
  )
}

// An ask past the day's limit: who asks what, then Send answers it once, outside the limit, or Cancel.
export function DraftCard(ctx: Ctx, draft: Draft): RenderElement {
  const { Box, Button, Text } = ctx.ui
  const warn = ctx.look.role.warn
  return (
    <Box key={`draft-${draft.qid}`} flexDirection="column" gap={1} backgroundColor={warn.tint} paddingX={1} paddingY={1}>
      <Text color={warn.fg} wrap="wrap">{chatWords().asking(firstName(draft.asker))}</Text>
      <Text color={ctx.look.hi} wrap="wrap">{draft.question}</Text>
      {ctx.model.canSettleDrafts
        ? (
          <Box flexDirection="row" gap={1}>
            <Button key={`draft-yes-${draft.qid}`} variant="primary" label={chatWords().send} onPress={() => ctx.on.settleDraft(draft.qid, true)} />
            <Button key={`draft-no-${draft.qid}`} label={chatWords().cancel} plain onPress={() => ctx.on.settleDraft(draft.qid, false)} />
          </Box>
        )
        : null}
    </Box>
  )
}

files.hooks/pane-bubble.tsx:
// A person's message on the desktop: a rounded bubble, mine in signal on the right, theirs on the card colour on
// the left (a project room puts their face beside the last of a run); a run shows its time once, under the last;
// a reply quotes what it answers; a DM that names a shared project room carries a chip to it; a message still
// going out is dashed and says so. System lines sit centred; an unreadable doc says it is one.
import type { RenderElement } from 'claude-code'

import { waitingText } from './connection'
import { GlyphPic, isText, Pic, receiptTone, type Ctx } from './pane-kit'
import { facePart } from './sig-chat'
import type { Line, RoomView } from './state-types'
import { avatarRole, initialsOf } from './theme'
import { messageOf } from './traffic'
import { clockText } from './when'
import { chatWords } from './words-chat'
import { shownSystem } from './words-wire'

const FACE = 24
const FACE_CELLS = 3
// The empty side of a bubble: about a fifth of the pane, so mine and theirs never line up into one column.
const GUTTER_RATIO = 0.18

export type BubbleOpts = { line: Line; isFirst: boolean; isLast: boolean; room: RoomView }

const gutterOf = (ctx: Ctx) => Math.max(4, Math.round(ctx.columns * GUTTER_RATIO))

// A message still going out says so, in amber while it waits for "Connect".
function pendingStatus(ctx: Ctx, line: Line): { text: string; color?: string } | null {
  if (line.receipt !== 'pending') return null
  return ctx.model.isConnected ? { text: chatWords().sending, color: ctx.look.lo } : { text: waitingText(), color: ctx.look.role.warn.fg }
}

// The time, then the receipt ticks or why it has none yet; text, so the host draws it in Claude's theme.
function Stamp(ctx: Ctx, line: Line, ts: number): RenderElement {
  const { Box, Text } = ctx.ui
  const status = pendingStatus(ctx, line)
  const tick = status === null && line.receipt !== undefined ? receiptTone(ctx, line.receipt) : null
  return (
    <Box key="stamp" flexDirection="row" justifyContent="flex-end" gap={1}>
      <Text color={ctx.look.lo}>{clockText(ts)}</Text>
      {status === null ? null : <Text color={status.color}>{status.text}</Text>}
      {tick === null ? null : <Text color={tick.color}>{tick.glyph}</Text>}
    </Box>
  )
}

// The message a reply answers: who wrote it and its first words, on the inset.
function Quote(ctx: Ctx, line: Line): RenderElement | null {
  const { Box, Text } = ctx.ui
  const quote = line.replyTo
  if (quote === undefined) return null
  return (
    <Box key="quote" flexDirection="column" backgroundColor={ctx.look.inset} paddingX={1}>
      <Text color={ctx.look.signal.fg} bold>{quote.name}</Text>
      <Text color={ctx.look.lo} wrap="truncate-end">{quote.text}</Text>
    </Box>
  )
}

// ⌥ partalemre/eliti ··· Go to room: a shared project room this DM names.
function RoomChip(ctx: Ctx, line: Line): RenderElement | null {
  const { Box, Button, Text } = ctx.ui
  const link = line.roomLink
  if (link === undefined) return null
  const run = ctx.look.role.run
  return (
    <Box key="room-chip" flexDirection="row" alignItems="center" gap={1} borderStyle="round" borderColor={run.line} backgroundColor={run.tint} paddingX={1}>
      {GlyphPic(ctx, { glyph: 'branch', paint: 'run', key: `chip-glyph-${line.id}` })}
      <Box flexGrow={1} flexShrink={1}><Text color={ctx.look.hi} wrap="truncate-end">{link.repo}</Text></Box>
      <Button key={`goto-${line.id}`} label={chatWords().goToRoom} plain onPress={() => ctx.on.select(link.roomId)} />
    </Box>
  )
}

function bubbleBody(ctx: Ctx, o: BubbleOpts & { text: string; ts: number }): RenderElement {
  const { Box, Text } = ctx.ui
  const { line } = o
  const tone = line.isMine ? ctx.look.signal : { tint: ctx.look.card, line: ctx.look.line }
  const isPending = line.receipt === 'pending'
  return (
    <Box flexDirection="column" borderStyle={isPending ? 'dashed' : 'round'} borderColor={tone.line} backgroundColor={tone.tint} paddingX={1} gap={0}>
      {Quote(ctx, line)}
      <Text key="text" color={ctx.look.hi} wrap="wrap">{o.text}</Text>
      {RoomChip(ctx, line)}
      {o.isLast || isPending ? Stamp(ctx, line, o.ts) : null}
    </Box>
  )
}

// Their face beside the last bubble of a run, a blank of its width beside the others; only project rooms show faces.
function Face(ctx: Ctx, o: BubbleOpts): RenderElement | null {
  const { line } = o
  if (o.room.kind !== 'project') return null
  if (o.isLast) return Pic(ctx, facePart({ initials: initialsOf(line.authorName), paint: avatarRole(line.seed), size: FACE }), `face-${line.id}`)
  const { Box } = ctx.ui
  return <Box key={`face-${line.id}`} width={FACE_CELLS} flexShrink={0} />
}

// Mine to the right with the gutter on the left; theirs to the left, behind their face in a project room.
function Side(ctx: Ctx, o: BubbleOpts & { body: RenderElement }): RenderElement {
  const { Box } = ctx.ui
  const { line } = o
  const gutter = gutterOf(ctx)
  if (line.isMine) return <Box key={`msg-${line.id}`} flexDirection="row" justifyContent="flex-end" paddingLeft={gutter}>{o.body}</Box>
  const face = Face(ctx, o)
  return (
    <Box key={`msg-${line.id}`} flexDirection="row" alignItems="flex-end" gap={1} paddingRight={gutter}>
      {face}
      {o.body}
    </Box>
  )
}

export function Bubble(ctx: Ctx, o: BubbleOpts): RenderElement {
  const { Box, Text } = ctx.ui
  const m = messageOf(o.line)
  if (m === null) return <Box key={`msg-${o.line.id}`} paddingLeft={FACE_CELLS + 1}><Text color={ctx.look.lo} italic>{chatWords().unreadable}</Text></Box>
  if (m.kind === 'system' || isText(ctx)) {
    return <Box key={`msg-${o.line.id}`} justifyContent="center"><Text color={ctx.look.lo} italic wrap="wrap">{shownSystem(m.text)}</Text></Box>
  }
  return Side(ctx, { ...o, body: bubbleBody(ctx, { ...o, text: m.text, ts: m.ts }) })
}

