// The composer on the desktop: the field (a placeholder addressed to the room) and "Send". A project room adds
// one "ask Leo's agent" button that opens the sheet of every query the protocol takes (one to a row, the free `ask`
// apart in Amber) and a removable mode chip once the field is set to one. A hint line shows only when it has
// something to say (an unknown command, a missing value).
import type { RenderElement } from 'claude-code'

import { ASK_DAILY_LIMIT } from './limits'
import { GlyphPic, Rule, within, type Ctx } from './pane-kit'
import { isModeType, specOf, supportedSpecs, type QuerySpec } from './query-menu'
import type { RoomView } from './state-types'
import { chatWords } from './words-chat'

const ASK_TYPE = 'ask'
// The sheet's border and padding, kept off its rule.
const SHEET_CHROME_CELLS = 4

export function placeholderOf(room: RoomView, mode: string | null): string {
  const arg = mode === null ? undefined : specOf(mode)?.arg
  if (arg !== undefined) return arg.placeholder
  const w = chatWords()
  if (room.kind === 'project') return w.placeProject
  return room.peerName === undefined ? w.placeAnyone : w.placePeer(room.peerName)
}

function AskButton(ctx: Ctx, room: RoomView): RenderElement {
  const { Button } = ctx.ui
  return <Button key={`ask-more-${room.id}`} label={ctx.model.isSheetOpen ? chatWords().close : chatWords().askAgent(room.peerName)} variant="secondary" onPress={() => ctx.on.toggleSheet(room.id)} />
}

// One query a row: its name to press, then what it returns.
function Cell(ctx: Ctx, o: { room: RoomView; spec: QuerySpec }): RenderElement {
  const { Box, Button, Text } = ctx.ui
  const isOn = ctx.model.composeMode === o.spec.type
  return (
    <Box key={`cell-${o.spec.type}`} flexDirection="row" alignItems="center" gap={1} paddingX={1} backgroundColor={isOn ? ctx.look.role.run.tint : undefined}>
      <Button key={`sheet-${o.spec.type}`} label={`${o.spec.type}${isModeType(o.spec.type) ? ' …' : ''}`} plain onPress={() => ctx.on.askAgent(o.room.id, o.spec.type)} />
      <Box flexGrow={1} flexShrink={1}><Text color={isOn ? ctx.look.mid : ctx.look.lo} wrap="truncate-end">{o.spec.desc}</Text></Box>
    </Box>
  )
}

function AskRow(ctx: Ctx, o: { room: RoomView; spec: QuerySpec }): RenderElement {
  const { Box, Button, Text } = ctx.ui
  return (
    <Box key="ask-row" flexDirection="row" alignItems="center" gap={1} paddingX={1}>
      {GlyphPic(ctx, { glyph: 'star', paint: 'warn', key: 'ask-star' })}
      <Box flexDirection="column" alignItems="flex-start" flexGrow={1} flexShrink={1}>
        <Button key={`sheet-${ASK_TYPE}`} label="ask …" plain onPress={() => ctx.on.askAgent(o.room.id, ASK_TYPE)} />
        <Text color={ctx.look.lo} wrap="truncate-end">{o.spec.desc}</Text>
      </Box>
      <Text color={ctx.look.mid}>{chatWords().perDay(ASK_DAILY_LIMIT)}</Text>
    </Box>
  )
}

// Ask Leo's agent ··· 12 ready queries · 0 tokens, the grid, then `ask …` apart.
function Sheet(ctx: Ctx, room: RoomView): RenderElement | null {
  const { Box, Text } = ctx.ui
  if (!ctx.model.isSheetOpen) return null
  const specs = supportedSpecs()
  const typed = specs.filter(s => s.type !== ASK_TYPE)
  const ask = specs.find(s => s.type === ASK_TYPE)
  const title = chatWords().sheetTitle(room.peerName)
  return (
    <Box key="sheet" flexDirection="column" gap={1} borderStyle="round" borderColor={ctx.look.lineStrong} backgroundColor={ctx.look.card} paddingX={1} paddingY={1}>
      <Box key="sheet-head" flexDirection="row" gap={1} paddingX={1}>
        <Box flexGrow={1}><Text color={ctx.look.role.run.fg} bold>{title}</Text></Box>
        <Text color={ctx.look.lo}>{chatWords().ready(typed.length)}</Text>
      </Box>
      <Box flexDirection="column">{typed.map(spec => Cell(ctx, { room, spec }))}</Box>
      {ask === undefined ? null : Rule(within(ctx, ctx.columns - SHEET_CHROME_CELLS), 'sheet-rule')}
      {ask === undefined ? null : AskRow(ctx, { room, spec: ask })}
    </Box>
  )
}

function ModeChip(ctx: Ctx): RenderElement | null {
  const { Box, Button, Text } = ctx.ui
  const mode = ctx.model.composeMode
  if (mode === null) return null
  const run = ctx.look.role.run
  return (
    <Box key="mode-chip" flexDirection="row" alignItems="center" gap={1} borderStyle="round" borderColor={run.line} backgroundColor={run.tint} paddingX={1} flexShrink={0}>
      <Text color={run.fg}>{mode}</Text>
      <Button key="mode-clear" label="×" plain onPress={() => ctx.on.clearMode()} />
    </Box>
  )
}

function HintRow(ctx: Ctx): RenderElement | null {
  const { Text } = ctx.ui
  const hint = ctx.model.hint
  return hint === null ? null : <Text key="hint" color={ctx.look.role.warn.fg} wrap="wrap">{hint}</Text>
}

export function Composer(ctx: Ctx, room: RoomView): RenderElement {
  const { Box, Text } = ctx.ui
  if (!('Input' in ctx.ui)) return <Text key="read-only" color={ctx.look.lo} wrap="wrap">{chatWords().readOnly}</Text>
  const { Input, Button } = ctx.ui
  const isProject = room.kind === 'project'
  const mode = ctx.model.composeMode
  return (
    <Box key="composer" flexDirection="column" gap={1}>
      {isProject ? Sheet(ctx, room) : null}
      <Box key="field-row" flexDirection="row" alignItems="center" gap={1}>
        {isProject && mode === null ? AskButton(ctx, room) : null}
        {ModeChip(ctx)}
        <Box flexGrow={1} flexDirection="column">
          <Input key={`composer-${room.id}-${ctx.model.composerKey}`} placeholder={placeholderOf(room, mode)} submitLabel={mode === null ? chatWords().send : chatWords().ask}
            autoFocus onInput={value => ctx.on.type(room.id, value)} onSubmit={value => ctx.on.send(room.id, value)} />
        </Box>
        <Button key={`send-${room.id}`} variant="primary" label={mode === null ? chatWords().send : chatWords().ask} onPress={() => ctx.on.sendTyped(room.id)} />
      </Box>
      {HintRow(ctx)}
    </Box>
  )
}

files.hooks/pane-term.tsx:
// One room on the terminal, the conversation first: the name and presence, one notice line only when something is
// wrong, the room's details only when asked, day rules, people's lines with their time, each agent exchange as one
// ◆ line that opens on press (a refusal as one ✕ line), a draft with its hotkeys, then the prompt line and its
// keys: the sheet of queries, the details and the way back.
import type { RenderElement } from 'claude-code'

import { compactOf } from './answers'
import { TIMELINE_LINES } from './limits'
import { fullIdOf } from './pane-agent'
import { RoomInfo } from './pane-aside'
import { GhCard, ShareCard } from './pane-cards'
import { firstLineOf, idsOf, isSameRun } from './pane-chat'
import { placeholderOf } from './pane-compose'
import { isHere, receiptTone, type Ctx } from './pane-kit'
import { noticeOf, statusOf } from './pane-words'
import { isModeType, supportedSpecs } from './query-menu'
import type { Draft, Line, RoomView } from './state-types'
import { avatarRole } from './theme'
import { waitingText } from './connection'
import { lang } from './kit/lang'
import { firstName } from './tr'
import { askedArg, itemsOf, joined, messageOf, queryType, type Item, type Tx } from './traffic'
import { answererOf, compactText, txSummary, viewLabel } from './tx-words'
import { clockText, dayKey, dayLower } from './when'
import { chatWords } from './words-chat'
import { tokensText } from './words-count'
import { shownSystem, shownWire } from './words-wire'

const SHEET_KEYS = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '0', 'w', 'y', 'z']

const lower = (text: string): string => text.toLocaleLowerCase(lang())

// A person's line as written; a system line in the reader's words (a moved mailbox).
const shownText = (m: NonNullable<ReturnType<typeof messageOf>>): string => (m.kind === 'system' ? shownSystem(m.text) : m.text)

// What is wrong, in one line, and "why?" when the room's details explain it.
function NoticeLine(ctx: Ctx, room: RoomView): RenderElement | null {
  const { Box, Button, Text } = ctx.ui
  const notice = noticeOf(room)
  if (notice === null) return null
  return (
    <Box key="notice" flexDirection="row" gap={1}>
      <Text color={ctx.look.role[notice.paint].fg} wrap="wrap">{notice.text}</Text>
      {notice.hasWhy && !ctx.model.isInfoOpen ? <Button key={`why-${room.id}`} label={chatWords().why.toLocaleLowerCase(lang())} plain onPress={() => ctx.on.toggleInfo(room.id)} /> : null}
    </Box>
  )
}

function Top(ctx: Ctx, room: RoomView): RenderElement {
  const { Box, Text } = ctx.ui
  const status = statusOf(room, { now: ctx.model.now, isHere: isHere(room, ctx.model.now) })
  return (
    <Box key="term-top" flexDirection="column">
      <Text><Text bold>{room.title}</Text>{status === null ? '' : '  '}<Text color={status?.isHere === true ? ctx.look.role.ok.fg : ctx.look.lo}>{status?.text ?? ''}</Text></Text>
      {NoticeLine(ctx, room)}
      {ctx.model.isInfoOpen ? RoomInfo(ctx, room) : null}
    </Box>
  )
}

// A reply's quote above it, a shared room's link under it.
function Extras(ctx: Ctx, line: Line): RenderElement[] {
  const { Box, Button, Text } = ctx.ui
  const link = line.roomLink
  return [
    ...(line.replyTo === undefined ? [] : [<Text key="quote" color={ctx.look.lo} wrap="truncate-end">{`  ↳ ${line.replyTo.name}: ${line.replyTo.text}`}</Text>]),
    ...(link === undefined ? [] : [<Box key="room-link" flexDirection="row" gap={1}><Text color={ctx.look.role.run.fg}>{`  ⌥ ${link.repo}`}</Text><Button key={`goto-${line.id}`} label={chatWords().goToRoom} plain onPress={() => ctx.on.select(link.roomId)} /></Box>]),
  ]
}

function HumanLine(ctx: Ctx, o: { line: Line; isFirst: boolean }): RenderElement {
  const { Box, Text } = ctx.ui
  const m = messageOf(o.line)
  const name = o.line.isMine ? chatWords().you : firstName(o.line.authorName)
  const color = o.line.isMine ? ctx.look.signal.fg : ctx.look.role[avatarRole(o.line.seed)].fg
  const tick = o.line.receipt === undefined ? null : receiptTone(ctx, o.line.receipt)
  const [quote, link] = [o.line.replyTo, o.line.roomLink]
  const extras = Extras(ctx, o.line)
  const row = (
    <Box key="row" flexDirection="row" gap={1}>
      <Text color={color} bold>{o.isFirst ? name : ' '.repeat(name.length)}</Text>
      <Box flexGrow={1}><Text wrap="wrap">{m === null ? chatWords().unreadable : shownText(m)}</Text></Box>
      <Text color={ctx.look.lo}>{m === null ? '' : clockText(m.ts)}</Text>
      {tick === null ? null : <Text color={tick.color}>{tick.glyph}</Text>}
    </Box>
  )
  if (quote === undefined && link === undefined) return <Box key={`msg-${o.line.id}`} flexDirection="column">{row}</Box>
  return <Box key={`msg-${o.line.id}`} flexDirection="column">{extras.slice(0, quote === undefined ? 0 : 1)}{row}{extras.slice(quote === undefined ? 0 : 1)}</Box>
}

// "show all" opens the whole answer under its exchange; "hide" folds it again.
function More(ctx: Ctx, o: { tx: Tx; body: string }): RenderElement {
  const { Box, Button, Text } = ctx.ui
  const id = fullIdOf(o.tx.id)
  const isOpen = ctx.model.expanded.includes(id)
  return (
    <Box key="more" flexDirection="column" alignItems="flex-start" paddingLeft={2}>
      {isOpen ? <Text wrap="wrap">{shownWire(o.body)}</Text> : null}
      <Button key={`more-${o.tx.id}`} label={lower(isOpen ? chatWords().hide : chatWords().showAll)} plain onPress={() => ctx.on.toggleExpanded(id)} />
    </Box>
  )
}

// An opened exchange: the question, who answered at what cost, the compact answer and its whole text.
function TxDetail(ctx: Ctx, tx: Tx): RenderElement[] {
  const { Text } = ctx.ui
  const a = joined(tx)
  const rail = a?.line.isMine === true ? ctx.look.signal.line : ctx.look.role.run.line
  const arg = askedArg(tx)
  const question = arg === undefined ? [] : [<Text key="question"><Text color={rail}>│ </Text>{arg}</Text>]
  if (a === null) return [...question, <Text key="waiting" color={ctx.look.lo}>{chatWords().waitingLine}</Text>]
  return [
    ...question,
    <Text key="who"><Text color={rail}>└ </Text>{a.line.isMine ? chatWords().thisMachineLower : answererOf(a)}<Text color={a.tokens === 0 ? ctx.look.signal.fg : ctx.look.lo}>{` · ${tokensText(a.tokens)}`}</Text></Text>,
    <Text key="compact" wrap="truncate-end">{`  ${compactText(compactOf(queryType(tx), a.body))}`}</Text>,
    More(ctx, { tx, body: a.body }),
  ]
}

function TxBlock(ctx: Ctx, tx: Tx): RenderElement {
  const { Box, Button, Text } = ctx.ui
  const s = txSummary(tx)
  const isDenied = s.outcome === 'denied'
  const isOpen = !isDenied && ctx.model.expanded.includes(tx.id)
  return (
    <Box key={`tx-${tx.id}`} flexDirection="column">
      <Box flexDirection="row" gap={1}>
        <Box flexGrow={1} flexShrink={1}>
          <Text color={isDenied ? ctx.look.role.danger.fg : ctx.look.role.run.fg} wrap="truncate-end">{`${isDenied ? '✕' : '◆'} ${s.text}`}</Text>
        </Box>
        {isDenied ? null : <Button key={`open-tx-${tx.id}`} label={lower(isOpen ? chatWords().hide : viewLabel(tx))} plain onPress={() => ctx.on.toggleExpanded(tx.id)} />}
      </Box>
      {isOpen ? TxDetail(ctx, tx) : null}
    </Box>
  )
}

function DraftBlock(ctx: Ctx, draft: Draft): RenderElement {
  const { Box, Button, Text } = ctx.ui
  return (
    <Box key={`draft-${draft.qid}`} flexDirection="column">
      <Text color={ctx.look.role.warn.fg}>{`● ${chatWords().asking(firstName(draft.asker))}`}</Text>
      <Text wrap="wrap">{`  ${draft.question}`}</Text>
      {ctx.model.canSettleDrafts
        ? <Box flexDirection="row" gap={2} paddingLeft={2}>
          <Button key={`draft-yes-${draft.qid}`} hotkey={chatWords().sendKey} label={chatWords().send} variant="primary" onPress={() => ctx.on.settleDraft(draft.qid, true)} />
          <Button key={`draft-no-${draft.qid}`} hotkey={chatWords().cancelKey} label={chatWords().cancel} plain onPress={() => ctx.on.settleDraft(draft.qid, false)} />
        </Box>
        : null}
    </Box>
  )
}

function itemsEls(ctx: Ctx, items: Item[]): RenderElement[] {
  const { Text } = ctx.ui
  const out: RenderElement[] = []
  const divider = ctx.model.divider
  items.forEach((item, i) => {
    const ts = messageOf(firstLineOf(item) as Line)?.ts ?? 0
    const prev = i > 0 ? messageOf(firstLineOf(items[i - 1] as Item) as Line)?.ts ?? 0 : null
    if (prev === null || dayKey(prev) !== dayKey(ts)) out.push(<Text key={`day-${idsOf(item)[0] ?? i}`} color={ctx.look.line}>{`──── ${dayLower(ts, ctx.model.now)} ────`}</Text>)
    if (divider !== null && idsOf(item).includes(divider.id)) out.push(<Text key="new-rule" color={ctx.look.signal.fg}>{`──── ${chatWords().newMessages(divider.count)} ────`}</Text>)
    out.push(item.kind === 'tx' ? TxBlock(ctx, item) : HumanLine(ctx, { line: item.line, isFirst: !isSameRun(items[i - 1], item) }))
  })
  return out
}

function Prompt(ctx: Ctx, room: RoomView): RenderElement {
  const { Box, Button, Text } = ctx.ui
  const mode = ctx.model.composeMode
  const Field = 'Input' in ctx.ui ? ctx.ui.Input : null
  const input = Field !== null
    ? <Field key={`composer-${room.id}-${ctx.model.composerKey}`} placeholder={placeholderOf(room, mode)} submitLabel={mode === null ? chatWords().sendLower : chatWords().askLower} onInput={v => ctx.on.type(room.id, v)} onSubmit={v => ctx.on.send(room.id, v)} />
    : <Text color={ctx.look.lo}>{placeholderOf(room, mode)}</Text>
  return (
    <Box key="prompt" flexDirection="row" gap={1} alignItems="center">
      <Text color={ctx.look.signal.fg}>›</Text>
      {mode === null ? null : <Text color={ctx.look.role.run.fg}>{`[${mode}]`}</Text>}
      {mode === null ? null : <Button key="mode-clear" hotkey="x" label={chatWords().plain} plain onPress={() => ctx.on.clearMode()} />}
      <Box flexGrow={1}>{input}</Box>
    </Box>
  )
}

function Keys(ctx: Ctx, room: RoomView): RenderElement {
  const { Box, Button, Text } = ctx.ui
  const isProject = room.kind === 'project'
